import{_ as d,o as e,c as r,j as t,a as l,a5 as s}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"给一颗宝石找到它的坐标","description":"从材料、结构、光学现象与颜色成因，建立宝石分类的第一张地图。","frontmatter":{"title":"给一颗宝石找到它的坐标","description":"从材料、结构、光学现象与颜色成因，建立宝石分类的第一张地图。"},"headers":[],"relativePath":"zh/classification/intro.md","filePath":"zh/classification/intro.md","lastUpdated":1790876393000}'),h={name:"zh/classification/intro.md"};function o(i,a,n,c,p,m){return e(),r("div",null,[...a[0]||(a[0]=[t("h1",{id:"给一颗宝石找到它的坐标",tabindex:"-1"},[l("给一颗宝石找到它的坐标 "),t("a",{class:"header-anchor",href:"#给一颗宝石找到它的坐标","aria-label":'Permalink to "给一颗宝石找到它的坐标"'},"​")],-1),t("blockquote",null,[t("p",null,"从材料、结构到光学现象，建立宝石世界的第一张地图。")],-1),t("p",null,"分类不是给宝石贴上一个标签，而是回答四个问题：它是什么、如何形成、如何呈现光，以及我们应该怎样继续认识它。",-1),t("div",{class:"classification-map",role:"list","aria-label":"宝石分类的四个观察入口"},[t("a",{class:"classification-map__item",href:"./mineral-groups/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"01"),t("strong",null,"材料属性"),t("span",null,"它是什么")]),t("a",{class:"classification-map__item",href:"./crystal-systems/cubic",role:"listitem"},[t("span",{class:"classification-map__index"},"02"),t("strong",null,"晶体结构"),t("span",null,"它如何排列")]),t("a",{class:"classification-map__item",href:"./optical-phenomena/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"03"),t("strong",null,"光学现象"),t("span",null,"它如何发光")]),t("a",{class:"classification-map__item",href:"./color-causes/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"04"),t("strong",null,"颜色成因"),t("span",null,"它为何有色")])],-1),s('<blockquote><p>这四个入口是四个互相交叉的观察坐标，不是四种互斥的类别。同一颗宝石可以同时拥有材料、结构、光学与颜色四组信息。</p></blockquote><h2 id="_01-·-它是什么-材料、成因与身份" tabindex="-1">01 · 它是什么：材料、成因与身份 <a class="header-anchor" href="#_01-·-它是什么-材料、成因与身份" aria-label="Permalink to &quot;01 · 它是什么：材料、成因与身份&quot;">​</a></h2><p>许多天然宝石与矿物有关，但宝石材料并不只有矿物。学习分类时，先判断“它是什么材料”，再判断“它从哪里来、是否经过处理”，最后确认它与其他宝石名称之间的关系。这样可以避免把材料、来源和仿制关系混成一条分类轴。</p><h3 id="a-先判断材料本身" tabindex="-1">A. 先判断材料本身 <a class="header-anchor" href="#a-先判断材料本身" aria-label="Permalink to &quot;A. 先判断材料本身&quot;">​</a></h3><table tabindex="0"><thead><tr><th>材料层级</th><th>学习者先问</th><th>代表材料</th></tr></thead><tbody><tr><td>天然矿物</td><td>是否有可用于界定它的化学组成与晶体结构？</td><td>刚玉、绿柱石、石英、金刚石</td></tr><tr><td>非晶质 / 类矿物材料</td><td>是否缺少典型的长程晶体有序结构？</td><td>欧泊、天然玻璃（如黑曜石）</td></tr><tr><td>有机材料</td><td>是否由生物活动或生物成因形成？</td><td>珍珠、琥珀、珊瑚</td></tr></tbody></table><h3 id="b-再判断来源与关系" tabindex="-1">B. 再判断来源与关系 <a class="header-anchor" href="#b-再判断来源与关系" aria-label="Permalink to &quot;B. 再判断来源与关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>身份维度</th><th>判断重点</th><th>例子</th></tr></thead><tbody><tr><td>天然</td><td>在自然环境中形成，未以实验室制造为来源</td><td>天然红宝石、天然欧泊</td></tr><tr><td>合成</td><td>在实验室制造，化学与结构可以接近天然对应物</td><td>合成红宝石、合成祖母绿、CVD 钻石</td></tr><tr><td>处理</td><td>对天然或合成材料进行人为处理，以改变外观或耐久性</td><td>加热、充填、染色等；应单独披露</td></tr><tr><td>复合 / 拼合</td><td>由两种或多种材料组合成一个成品</td><td>双层石、三层石</td></tr><tr><td>仿制</td><td>用另一种材料模拟目标宝石的外观；不等于某一种固定材料</td><td>立方氧化锆、玻璃、作为钻石仿制品的莫桑石</td></tr></tbody></table><blockquote><p>学习口诀：<strong>材料是什么？从哪里来？是否经过处理？是否在模仿另一种宝石？</strong> 这四个问题应分别回答。</p></blockquote><h3 id="c-最后确认名称所在层级" tabindex="-1">C. 最后确认名称所在层级 <a class="header-anchor" href="#c-最后确认名称所在层级" aria-label="Permalink to &quot;C. 最后确认名称所在层级&quot;">​</a></h3><p>GIA 将相关名称分成三个常用层级：**矿物组 / 族（group）**包含相互关联的矿物种；**矿物种（species）**由化学组成与晶体结构界定；**宝石品种（variety）**则常由颜色或其他可见特征区分。</p><table tabindex="0"><thead><tr><th>层级示例</th><th>关系</th><th>入门示例</th></tr></thead><tbody><tr><td>矿物种 → 宝石品种</td><td>一个矿物种可以对应多个宝石品种</td><td>刚玉 → 红宝石、蓝宝石</td></tr><tr><td>矿物种 → 宝石品种</td><td>颜色与外观特征形成常用宝石名称</td><td>绿柱石 → 祖母绿、海蓝宝、摩根石</td></tr><tr><td>矿物组 → 多个矿物种</td><td>一个矿物组可以包含多个相关矿物种</td><td>石榴石组 → 多种石榴石矿物种与品种</td></tr><tr><td>矿物种 → 商业外观分类</td><td>同一矿物种还可以按颜色或市场语境继续描述</td><td>金刚石 → 无色钻石、彩钻</td></tr></tbody></table><blockquote><p>“贵重宝石”和“半贵重宝石”是传统商业语境中的称呼，不是现代宝石学的严格科学分类。判断价值时，更应关注稀有度、美观度、耐久性、处理情况与市场需求。</p></blockquote><p><strong>参考依据：</strong> <a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA：宝石的矿物种、品种与矿物组</a> · <a href="https://www.gia.edu/gem-synthetic" target="_blank" rel="noreferrer">GIA：合成宝石材料</a> · <a href="https://www.gia.edu/gem-imitation" target="_blank" rel="noreferrer">GIA：仿制宝石</a> · <a href="https://www.gia.edu/FAQ/gia-faq-about-gemstones-difference-treatment-enhancement" target="_blank" rel="noreferrer">GIA：宝石处理与优化常见问答</a></p><h2 id="_02-·-它如何排列-晶系与结构" tabindex="-1">02 · 它如何排列：晶系与结构 <a class="header-anchor" href="#_02-·-它如何排列-晶系与结构" aria-label="Permalink to &quot;02 · 它如何排列：晶系与结构&quot;">​</a></h2><p>晶体结构描述原子或离子在空间中的有序排列。七大晶系依据晶体的对称性与晶轴关系进行描述；它是理解光性、解理、晶体习性与部分鉴定线索的结构坐标，不是对成品外观的简单命名。</p><h3 id="七大晶系-描述晶体对称性" tabindex="-1">七大晶系：描述晶体对称性 <a class="header-anchor" href="#七大晶系-描述晶体对称性" aria-label="Permalink to &quot;七大晶系：描述晶体对称性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>晶系</th><th>结构特征</th><th>代表宝石</th><th>学习提示</th></tr></thead><tbody><tr><td><a href="./crystal-systems/cubic.html">等轴晶系</a></td><td>三轴等长，彼此正交</td><td>钻石、尖晶石、石榴石</td><td>七大晶系中对称性最高</td></tr><tr><td><a href="./crystal-systems/tetragonal.html">四方晶系</a></td><td>两轴等长且正交，第三轴不同</td><td>锆石、金红石</td><td>留意两条相等轴与主轴的差异</td></tr><tr><td><a href="./crystal-systems/orthorhombic.html">斜方晶系</a></td><td>三轴不等，彼此正交</td><td>坦桑石、亚历山大石、托帕石</td><td>三个直角关系仍然保留</td></tr><tr><td><a href="./crystal-systems/hexagonal.html">六方晶系</a></td><td>具有六重主对称轴</td><td>绿柱石、磷灰石</td><td>与三方晶系的主轴对称性区分</td></tr><tr><td><a href="./crystal-systems/trigonal.html">三方晶系</a></td><td>具有三重主对称轴</td><td>红宝石、蓝宝石、石英、电气石</td><td>刚玉、石英和电气石是重要宝石族</td></tr><tr><td><a href="./crystal-systems/monoclinic.html">单斜晶系</a></td><td>三轴不等，只有两组夹角为直角</td><td>正长石、锂辉石</td><td>结构各向异性会影响光性与解理</td></tr><tr><td><a href="./crystal-systems/triclinic.html">三斜晶系</a></td><td>三轴不等，夹角均不为直角</td><td>蓝晶石、绿松石</td><td>七大晶系中对称性最低</td></tr></tbody></table><p><span id="amorphous-materials"></span></p><h3 id="非晶质材料-不属于晶系" tabindex="-1">非晶质材料：不属于晶系 <a class="header-anchor" href="#非晶质材料-不属于晶系" aria-label="Permalink to &quot;非晶质材料：不属于晶系&quot;">​</a></h3><p>欧泊、天然玻璃（如黑曜石）和琥珀不应作为“第八种晶系”列入上表。它们需要以材料结构单独描述：没有完整的长程晶体有序结构，因此不能直接套用七大晶系的晶轴关系。</p><table tabindex="0"><thead><tr><th>材料状态</th><th>代表材料</th><th>学习重点</th></tr></thead><tbody><tr><td>非晶质 / 类矿物</td><td>欧泊</td><td>关注含水二氧化硅结构与变彩，而不是寻找所属晶系</td></tr><tr><td>天然玻璃</td><td>黑曜石</td><td>关注玻璃质结构与形成环境，而不是用晶体对称性分类</td></tr><tr><td>有机材料</td><td>琥珀</td><td>先按有机成因理解，再与矿物晶体分类区分</td></tr></tbody></table><blockquote><p>对已经切磨的成品，不能只凭轮廓判断晶系。晶系通常需要结合矿物学资料、光性、折射率、双折射和晶体结构证据来理解。</p></blockquote><h3 id="三个容易混淆的词" tabindex="-1">三个容易混淆的词 <a class="header-anchor" href="#三个容易混淆的词" aria-label="Permalink to &quot;三个容易混淆的词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>它描述什么</th><th>不要把它误解成</th></tr></thead><tbody><tr><td>晶系</td><td>内部结构的对称性与晶轴关系</td><td>一颗宝石看起来像什么形状</td></tr><tr><td>晶形 / 晶习</td><td>晶体在生长过程中形成的外部形态</td><td>切割师最后加工出的轮廓</td></tr><tr><td>切工</td><td>人为设计的刻面、比例与抛光方式</td><td>宝石天然属于哪一种晶系</td></tr></tbody></table><p><em>从<a href="./crystal-systems/cubic.html">等轴晶系</a>开始，逐页观察晶体结构与宝石性质的关系。</em></p><p><strong>参考依据：</strong> <a href="https://www.open.edu/openlearn/science-maths-technology/an-introduction-minerals-and-rocks-under-the-microscope/content-section-1.6.3/?tip=linktip" target="_blank" rel="noreferrer">Open University：晶体系统</a> · <a href="https://australian.museum/learn/minerals/what-are-minerals/crystallography/" target="_blank" rel="noreferrer">Australian Museum：晶体学</a> · <a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA：现象宝石的结构</a></p><h2 id="_03-·-它如何呈现光-光学现象" tabindex="-1">03 · 它如何呈现光：光学现象 <a class="header-anchor" href="#_03-·-它如何呈现光-光学现象" aria-label="Permalink to &quot;03 · 它如何呈现光：光学现象&quot;">​</a></h2><p>光学现象是观察宝石的重要入口，但现象名称、成因和商业名称不应混为一谈。本项目将“看见的效果”“如何观察”与“产生效果的结构或包裹体”分开记录。</p><table tabindex="0"><thead><tr><th>现象</th><th>主要表现</th><th>如何观察</th><th>代表材料</th></tr></thead><tbody><tr><td>星光效应</td><td>光线形成交叉星芒</td><td>单点光源直射，缓慢转动弧面宝石</td><td>星光红宝石、星光蓝宝石</td></tr><tr><td>猫眼效应</td><td>出现一条可移动的亮带</td><td>移动光源或转动弧面宝石，观察光带是否移动</td><td>猫眼金绿宝石、虎睛石</td></tr><tr><td>变色效应</td><td>在不同光源下呈现不同颜色</td><td>在日光与白炽或暖色光源下分别观察</td><td>亚历山大石、变色蓝宝石</td></tr><tr><td>变彩 / 游彩</td><td>随角度变化出现彩色闪光</td><td>缓慢倾斜宝石，观察色斑的移动与分布</td><td>欧泊</td></tr><tr><td>晕彩</td><td>薄层或层状结构产生干涉色</td><td>改变观察角度，观察大面积色带变化</td><td>拉长石等</td></tr><tr><td>月光效应</td><td>出现柔和的蓝白色漂浮光晕</td><td>转动弧面宝石，观察光晕的漂移</td><td>月光石</td></tr><tr><td>砂金效应</td><td>内部片状包裹体产生闪烁</td><td>倾斜宝石，让片状包裹体依次反射光线</td><td>砂金石、日光石</td></tr></tbody></table><blockquote><p>观察到一个现象，只能说明“它呈现了某种光学表现”，不能单独作为最终鉴定结论。光源、切磨形状、观察角度和内部包裹体都会影响结果。</p></blockquote><p><em>进入<a href="./optical-phenomena/intro.html">光学现象</a>，查看各类效果的成因、观察方式与鉴定提示。</em></p><h2 id="_04-·-它为何有色-颜色成因" tabindex="-1">04 · 它为何有色：颜色成因 <a class="header-anchor" href="#_04-·-它为何有色-颜色成因" aria-label="Permalink to &quot;04 · 它为何有色：颜色成因&quot;">​</a></h2><p>颜色不是孤立的外观标签，而是光与物质相互作用后的结果。先分清“吸收型体色”和“结构型光学色”，再进入具体机制：红宝石的红色主要来自选择性吸收，而欧泊的变彩来自微结构对光的衍射与干涉。</p><table tabindex="0"><thead><tr><th>观察路径</th><th>光线发生了什么</th><th>典型结果</th></tr></thead><tbody><tr><td>吸收型体色</td><td>宝石选择性吸收部分可见光，剩余光线进入眼睛</td><td>红宝石、祖母绿、蓝宝石的体色</td></tr><tr><td>结构型光学色</td><td>微结构使光发生散射、干涉或衍射，颜色随角度或光源改变</td><td>欧泊变彩、月光石月光效应、拉长石晕彩</td></tr></tbody></table><h3 id="三类常见的吸收致色机制" tabindex="-1">三类常见的吸收致色机制 <a class="header-anchor" href="#三类常见的吸收致色机制" aria-label="Permalink to &quot;三类常见的吸收致色机制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>核心问题</th><th>代表方向</th></tr></thead><tbody><tr><td>过渡金属离子</td><td>晶格中的离子选择性吸收哪些可见光</td><td>铬、铁、锰、钴、铜等</td></tr><tr><td>色心</td><td>晶格缺陷如何改变光的吸收</td><td>空位、间隙与辐照相关缺陷</td></tr><tr><td>电荷转移</td><td>电子在相邻离子或能级之间如何跃迁</td><td>金属—金属、氧—金属等</td></tr></tbody></table><p>颜色分类适合帮助观察和检索，但不能替代鉴定。同一种颜色可能来自不同机制；真正的颜色描述还要结合色相、明度、饱和度、光源和观察方向。</p><p><em>详见<a href="./color-causes/intro.html">颜色成因</a>，从物理化学机制理解宝石为什么会呈现不同颜色。</em></p><h2 id="_05-·-从分类坐标进入宝石名录" tabindex="-1">05 · 从分类坐标进入宝石名录 <a class="header-anchor" href="#_05-·-从分类坐标进入宝石名录" aria-label="Permalink to &quot;05 · 从分类坐标进入宝石名录&quot;">​</a></h2><p>同一颗宝石可以同时拥有多个坐标：例如欧泊属于非晶质材料，也可能呈现变彩 / 游彩；蓝宝石是刚玉这一矿物种中的宝石品种，并具有三方晶系。分类不是把宝石放进唯一的盒子，而是建立多维检索关系。</p><p>GemAtlas 中的每颗宝石都拥有独立页面，展示其物理性质、光学特征、处理方式与参考文献。你可以按<a href="./mineral-groups/intro.html">矿物分类组</a>、<a href="./crystal-systems/cubic.html">晶系</a>或<a href="./optical-phenomena/intro.html">光学现象</a>继续探索；准备浏览完整收录对象时，可进入<a href="./../gems/">宝石名录</a>。</p><div class="classification-index-cta"><span class="classification-index-cta__count">60</span><div><strong>宝石名录 · The Stone Index</strong><p>全部 60 种宝石集中于一个可浏览的学习入口，从名称、矿物族到独立详页逐层展开。</p></div><a href="../gems/">浏览全部收录 ↗</a></div>',42)])])}const f=d(h,[["render",o]]);export{u as __pageData,f as default};
